// self-clear: at a context threshold, have Claude write a checkpoint, check it was written,
// run /clear, then (optionally) resume from the checkpoint.
// Installed globally (user scope) but OFF unless a project opts in with .claude/self-clear.json
// {"enabled": true, ...}: clearing a conversation is never done where nobody asked for it.
// Written against Claude Code v2.1.286 mods (tested up to 2.1.295).
//
// Cycle: idle → (turn ends ≥ threshold, no subagent running) ask for a checkpoint carrying a token
//   → (a turn ends) newest checkpoint file changed since the ask AND contains the token,
//     no subagent running, nobody typed since → /clear → resume prompt with the file's full path → idle.
// It never clears without a fresh checkpoint written for this cycle.
// Spawn gate (opt-in): a cycle can also start mid-turn. When the main loop starts a subagent at or above the
//   threshold, the spawn is refused and the refusal carries the checkpoint request; while a cycle runs,
//   every new main-loop subagent is refused, so a turn that chains subagents drains and ends, and the turn end
//   clears as above. The clear waits for any background work (timers excluded). Off unless the project
//   file sets "gateSpawns": true.

const PROJECT_FILE = '.claude/self-clear.json'
const MIN_THRESHOLD = 200000
const MAX_THRESHOLD = 850000   // stay well below the engine's own autocompact (~967K seen on 1M models)
const ASKS = 2                 // checkpoint requests before giving up on this cycle
const RETRIES = 3              // /clear attempts
const RETRY_MS = 2000
const MAX_WAIT_TURNS = 3       // turn ends above threshold + WAIT_MARGIN that may wait on background work before asking anyway
const WAIT_MARGIN = 100000
const MAX_MACHINE_REASKS = 3   // non-person inputs during one checkpoint phase before the cycle is dropped
const MAX_TOTAL_ASKS = 3       // checkpoint asks in one cycle, whatever the cause (more than this is treated as a fault)
// Prompts from these origins are machinery, not a person typing: they do not cancel a cycle; they only
// make an earlier checkpoint stale (see prompt.submit).
// Any other kind (including ones added later) still counts as a person: cancelling is the safe side.
const MACHINE_ORIGINS = ['plugin', 'task-notification', 'scheduled-trigger', 'peer', 'peer-send-message',
  'coordinator', 'observer', 'observer-activity', 'auto-continuation']
// A background shell that only waits (a wake-up timer such as `timeout 300 sleep 290; echo wake`) is not work.
const TIMER = /^\s*(?:timeout\s+\d+\s+)?sleep\s+\d+(?:\.\d+)?\s*(?:(?:;|&&)\s*echo(?:\s+[\w-]+)?\s*)?$/i

const DEFAULTS = {
  // Not under .claude/: that is a protected path (writes prompt, or go to the auto-mode classifier).
  checkpointDir: '.tmp/self-clear',
  checkpointPrefix: 'checkpoint',
  checkpointPrompt:
    'The self-clear mod (a plugin message, not the user\'s words; never quote it as the user): ' +
    'context is at {tokens}K, so this session will be cleared. ' +
    'Write a checkpoint now as a NEW file in {dir}/ named "{file}" (do not reuse an existing file). Include ' +
    'the goal, what is done (with proof), what is in progress, open questions to the user in their exact words, ' +
    'files changed but not committed, and the exact next step. Put this line in the file exactly: {tokenLine} ' +
    'Do no other work, then end your turn.',
  resumePrompt:
    'The self-clear mod cleared this session after your checkpoint (a plugin message, not the user\'s words; never quote it as the user). ' +
    'Read {checkpoint} and continue from its next step. If it says you were waiting for the user, ' +
    'restate the open question in one line and stop.',
}

// Module state. Resets on reload; a reload mid-cycle simply ends that cycle.
let phase = 'idle'      // 'idle' | 'checkpoint' | 'clearing'
let askedAt = 0
let asks = 0
let token = ''
let userSpoke = false   // a prompt that did not come from this mod arrived during the cycle
let backgroundTasks = 0 // in-flight background work (shell, subagent, monitor, workflow) at the last Stop, timers excluded
let waitedTurns = 0     // turn ends above threshold + WAIT_MARGIN that waited on background work
let machineReasks = 0   // non-person inputs during this checkpoint phase
let lateInput = false   // a non-person input arrived after the clear was scheduled
let tokenSeq = 0        // makes every token distinct; never reset
let tokenTag = ''       // session id + time, set by the first token; lets later tokens be made with no await
let totalAsks = 0       // checkpoint asks in this cycle
let inputGen = 0        // bumped at once (before any await) by every input that arrives during a cycle
let gateSuspended = 0   // after a dropped cycle, how many main-loop spawns the gate lets through before it may start a new cycle
let gateRefusals = 0    // spawns refused in this cycle
let gateOn = false      // the gate setting at the last config read (prompt.submit must not await a read)
let busyWaits = 0       // turn ends that found the checkpoint ready but background work still running
let readyBusy = false   // set after MAX_WAIT_TURNS such turn ends: the gate opens; the clear still waits
let oldNames = new Set() // note names already in the folder before this cycle's first ask (lower case)
let skippedNames = []   // fresh notes skipped at the last check because of their file name
let reusedNames = []    // fresh notes skipped because the name was already in the folder before the cycle
let snapshotFailed = false // the folder could not be listed at the first ask (other than missing): trust no note
let abandoned = ''      // token of a clear the watchdog gave up on; a late /clear result for it is ignored
let blocked = false     // the note folder leads outside the project: no cycle in this session
let announced = false   // the "on in this project" notice was shown in this session
let dropStreak = 0      // cycles in a row that ended without a clear
let pausedBelow = 0     // after DROPS_BEFORE_PAUSE such cycles: no new cycle until the context reaches this
let lastAskTokens = 0   // context size at the last ask

// Two cycles in a row that end without a clear (for example a folder Claude cannot write to) would
// otherwise ask again at every turn end. So the mod then waits until the context grows by PAUSE_GROWTH.
const DROPS_BEFORE_PAUSE = 2
const CLEAR_WATCHDOG_MS = 60000
const PAUSE_GROWTH = 100000

function reset() {
  oldNames = new Set()
  snapshotFailed = false
  gateRefusals = 0
  gateSuspended = 0
  busyWaits = 0
  readyBusy = false
  waitedTurns = 0
  totalAsks = 0
  machineReasks = 0
  lateInput = false
  phase = 'idle'
  asks = 0
  token = ''
  userSpoke = false
}

// A cycle that ends without a clear (dropped, cancelled, refused, aborted). The gate then lets the next few
// main-loop spawns through before it may start a new cycle, so a cycle that cannot finish never holds the
// work, even inside one long turn. A turn end above the threshold still starts the next cycle at once.
const GATE_SUSPEND_SPAWNS = 3
// noNote: the cycle ended because no usable note was written. Only these count toward the pause;
// a cycle the person interrupted (typing, Esc) does not.
function drop(noNote = false) {
  reset()
  gateSuspended = GATE_SUSPEND_SPAWNS
  if (!noNote) return
  dropStreak += 1
  if (dropStreak >= DROPS_BEFORE_PAUSE) pausedBelow = lastAskTokens + PAUSE_GROWTH
}

const paused = (tokens) => tokens < pausedBelow

function num(v, fallback, lo, hi) {
  const n = typeof v === 'number' ? v : NaN
  return Math.min(hi, Math.max(lo, Number.isFinite(n) ? n : fallback))
}

function fill(text, values) {
  return text.replace(/\{(\w+)\}/g, (m, k) => (Object.prototype.hasOwnProperty.call(values, k) ? String(values[k]) : m))
}

// The project file is repository content: a cloned repo may ship it. So it may only name a checkpoint
// folder inside the project (plain relative segments, no "..", no absolute or network path) and a plain
// file-name prefix, and it cannot change the prompts. Anything else falls back to the default.
const SAFE_SEGMENT = /^[A-Za-z0-9_][A-Za-z0-9._-]{0,63}$/
const SAFE_PREFIX = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/
const SAFE_NAME = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/
const MAX_CHECKPOINT_BYTES = 1000000
const MAX_FILES_CHECKED = 5

// Windows device names: a folder or file named like this is a device, not a file.
const RESERVED = /^(con|prn|aux|nul|com[0-9]|lpt[0-9]|conin\$|conout\$)(\..*)?$/i

function safeDir(v) {
  if (typeof v !== 'string') return null
  const parts = v.replace(/[\\/]+$/, '').split(/[\\/]+/)
  if (parts.length < 1 || parts.length > 8) return null
  if (!parts.every((x) => SAFE_SEGMENT.test(x) && !/\.$/.test(x) && !RESERVED.test(x))) return null
  return parts.join('/')
}

function safePrefix(v) {
  return typeof v === 'string' && SAFE_PREFIX.test(v) && !RESERVED.test(v) ? v : null
}

// The folder name is checked above, but a cloned repo can also commit one of its folders as a link
// (symlink or junction), or reach one through a case alias. So the real path is what counts: the
// deepest part of the folder that exists must resolve to a place inside the project's own real path.
// A path that cannot be resolved is not trusted, but only a resolved path outside the project turns
// the mod off for the session (a passing lock or permission error just skips this ask).
function isUnder(real, rootReal) {
  const win = rootReal.includes('\\')
  const a = win ? real.toLowerCase() : real
  const b = win ? rootReal.toLowerCase() : rootReal
  const sep = win ? '\\' : '/'
  const base = b.endsWith(sep) ? b : b + sep
  return a === b || a.startsWith(base)
}

async function realOf($, path) {
  const st = await $.fs.stat(path, { resolve: true }).catch(() => null)
  return st && typeof st.realPath === 'string' ? st.realPath : null
}

// The project root, keeping the separator of a drive or share root ("C:\", "/") so it stays absolute.
async function projectRoot($) {
  const raw = await $.session.root()
  const sep = raw.includes('\\') ? '\\' : '/'
  const trimmed = raw.replace(/[\\/]+$/, '')
  const root = trimmed === '' || /^[A-Za-z]:$/.test(trimmed) ? trimmed + sep : trimmed
  const join = (rel) => (root.endsWith(sep) ? root : root + sep) + rel.replace(/^[\\/]+/, '').replace(/[\\/]+/g, sep)
  return { root, sep, join }
}

// 'inside' | 'outside' | 'unknown'. The deepest part of the folder that exists must resolve inside
// the project's own real path; a part that does not exist yet is skipped (fs.exists, no error text).
async function folderPlace($, rel) {
  try {
    const { root, join } = await projectRoot($)
    const rootReal = await realOf($, root)
    if (!rootReal) return 'unknown'
    const parts = rel.split('/')
    for (let n = parts.length; n >= 1; n -= 1) {
      const path = join(parts.slice(0, n).join('/'))
      if (!(await $.fs.exists(path))) continue
      const real = await realOf($, path)
      if (!real) return 'unknown'
      return isUnder(real, rootReal) ? 'inside' : 'outside'
    }
    return 'inside'   // nothing of the folder exists yet: Claude creates it inside the project root
  } catch (err) {
    return 'unknown'
  }
}

async function insideProject($, rel) {
  return (await folderPlace($, rel)) === 'inside'
}

// Project paths resolve from the project root, not the shell's cwd: a `cd` must not hide them.
// Joined with the root's own separator, so a Windows root gives a plain Windows path.
// Only relative paths reach here (see safeDir): the checkpoint folder always lives inside the project.
async function rootPath($, rel) {
  return (await projectRoot($)).join(rel)
}

// null: no file. { bad: reason }: a file that is not a small, plain JSON object. Otherwise the object.
// The file is repository content, so it must be a plain file (not a link, a device or a pipe) and small.
const MAX_PROJECT_FILE_BYTES = 65536
async function readProjectFile($) {
  try {
    const path = await rootPath($, PROJECT_FILE)
    if (!(await $.fs.exists(path))) return null
    const st = await $.fs.stat(path)
    if (!st || st.kind !== 'file' || st.isLink || st.size > MAX_PROJECT_FILE_BYTES) return { bad: 'not a small plain file' }
    const parsed = JSON.parse(String(await $.fs.read(path)).replace(/^\uFEFF/, ''))
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : { bad: 'not a JSON object' }
  } catch (err) {
    $.ui.log('self-clear: ignoring ' + PROJECT_FILE + ': ' + err, { to: 'debug' })
    return { bad: 'not valid JSON' }
  }
}

async function loadConfig($, options) {
  const cfg = await readConfig($, options)
  gateOn = cfg.enabled && cfg.gateSpawns && !blocked
  // A project file (possibly from a cloned repo) turned the mod on: say so once, with what it set.
  if (cfg.enabled && !announced) {
    announced = true
    $.ui.toast('self-clear is on in this project: clears at ' + Math.round(cfg.threshold / 1000) + 'K, auto-resume ' +
      (cfg.autoResume ? 'on' : 'off') + ', spawn gate ' + (cfg.gateSpawns ? 'on' : 'off') + '. Type /self-clear for details.')
  }
  return cfg
}

async function readConfig($, options) {
  const read = await readProjectFile($)
  const bad = read && read.bad ? read.bad : ''
  const file = bad ? null : read
  const p = file || {}
  const pick = (v, d) => (v === undefined || v === null ? d : v)
  return {
    hasFile: read !== null,
    bad,
    enabled: file !== null && p.enabled === true,
    threshold: num(pick(p.thresholdTokens, options.threshold_tokens), 500000, MIN_THRESHOLD, MAX_THRESHOLD),
    autoResume: pick(p.autoResume, pick(options.auto_resume, false)) === true,
    dir: safeDir(p.checkpointDir) || DEFAULTS.checkpointDir,
    prefix: safePrefix(p.checkpointPrefix) || DEFAULTS.checkpointPrefix,
    checkpointPrompt: DEFAULTS.checkpointPrompt,
    resumePrompt: DEFAULTS.resumePrompt,
    gateSpawns: p.gateSpawns === true || p.gateSpawns === 'true',   // off unless switched on
  }
}

async function contextTokens($) {
  const usage = await $.session.usage()
  return (usage && usage.context && usage.context.tokens) || 0
}

// Work still running in the background — subagents (for example reviewers or helpers) and the
// background tasks the last Stop event listed (run_in_background shells such as a test run,
// monitors, workflows). Clearing now would lose track of the results, so the cycle waits.
async function runningWork($) {
  let agents = 0
  try {
    agents = (await $.agent.list()).filter((a) => a.status === 'running').length
  } catch (err) {
    agents = 0
  }
  return agents + backgroundTasks
}

// Absolute path of the newest checkpoint file changed since `since` that carries this cycle's token;
// null when there is none. The token stops another session's checkpoint, or a stale or half-written
// file, from passing as this session's.
// A note that already sat in the folder before this cycle's first ask (for example one a cloned repo
// ships) never counts, even if Claude appends the token to it: the ask is for a new file.
async function snapshotOld($, cfg, before) {
  try {
    if (!(await insideProject($, cfg.dir))) { snapshotFailed = true; return }   // could not check: trust no note
    const dir = await rootPath($, cfg.dir)
    if (!(await $.fs.exists(dir))) { oldNames = new Set(); return }   // no folder yet: nothing old in it
    const entries = await $.fs.list(dir)
    // Every name already there counts as old, whatever its date (an archive can carry a future one).
    oldNames = new Set(entries.map((f) => f.name.toLowerCase()))
  } catch (err) {
    // No folder yet: nothing old in it. Any other failure: trust no note in this cycle.
    if (!String(err).includes('ENOENT')) snapshotFailed = true
    oldNames = new Set()
  }
}

const prefixed = (f, cfg) => f.name.toLowerCase().startsWith(cfg.prefix.toLowerCase())

async function freshCheckpoint($, cfg, since, want) {
  skippedNames = []
  reusedNames = []
  if (snapshotFailed) return null
  try {
    if (!(await insideProject($, cfg.dir))) {
      $.ui.log('self-clear: ' + cfg.dir + ' leads outside the project; not reading it', { to: 'debug' })
      return null
    }
    const rootReal = await realOf($, (await projectRoot($)).root)
    const dir = await rootPath($, cfg.dir)
    const entries = await $.fs.list(dir)
    const recent = entries.filter((f) => f.kind === 'file' && !f.isLink && prefixed(f, cfg) && f.mtimeMs >= since)
    skippedNames = recent.filter((f) => !SAFE_NAME.test(f.name) || RESERVED.test(f.name)).map((f) => f.name)
    reusedNames = recent.filter((f) => oldNames.has(f.name.toLowerCase())).map((f) => f.name)
    const fresh = recent
      .filter((f) => SAFE_NAME.test(f.name) && !RESERVED.test(f.name) && !oldNames.has(f.name.toLowerCase())
        && !(f.size > MAX_CHECKPOINT_BYTES))
      .sort((a, b) => b.mtimeMs - a.mtimeMs)
      .slice(0, MAX_FILES_CHECKED)
    for (const f of fresh) {
      const path = dir + (dir.includes('\\') ? '\\' : '/') + f.name
      const real = await realOf($, path)
      if (!real || !rootReal || !isUnder(real, rootReal)) continue
      if (String(await $.fs.read(path)).includes(want)) return path
    }
    return null
  } catch (err) {
    $.ui.log('self-clear: cannot check ' + cfg.dir + ': ' + err, { to: 'debug' })
    return null
  }
}

// A new token every time one is needed: a checkpoint file is often rewritten in place, so a
// token line from an earlier ask can still be in it and must not pass as this one.
async function newToken($) {
  if (!tokenTag) tokenTag = (await $.session.id()).slice(0, 8) + '-' + (await $.clock.now()).toString(36)
  return nextToken()
}

// The cycle's token, made once: the only awaits come before the re-check, so two callers that race
// (parallel spawns, "/self-clear now") end up with the same token.
async function ensureToken($) {
  if (!tokenTag) tokenTag = (await $.session.id()).slice(0, 8) + '-' + (await $.clock.now()).toString(36)
  if (!token) token = nextToken()
  return token
}

// Synchronous: used where an await would leave a moment in which the old token still counts.
function nextToken() {
  tokenSeq += 1
  return 'self-clear-token: ' + (tokenTag || 'x') + '-' + tokenSeq
}

// A file name made by the mod for this ask: prefix, then the UTC date and time of the ask.
function noteName(cfg) {
  const d = new Date(askedAt || 0)
  const two = (n) => String(n).padStart(2, '0')
  return cfg.prefix + '-' + d.getUTCFullYear() + two(d.getUTCMonth() + 1) + two(d.getUTCDate()) + '-' +
    two(d.getUTCHours()) + two(d.getUTCMinutes()) + two(d.getUTCSeconds()) + '.md'
}

function requestText(cfg, tokens, tokenLine) {
  return fill(cfg.checkpointPrompt, { tokens: Math.round(tokens / 1000), dir: cfg.dir, prefix: cfg.prefix, file: noteName(cfg), tokenLine })
}

// Counts one ask and enters the checkpoint phase; false when this cycle has asked too often (it is dropped).
async function beginAsk($, tokens) {
  if (totalAsks >= MAX_TOTAL_ASKS) {
    drop(true)
    $.ui.toast('self-clear: asked ' + MAX_TOTAL_ASKS + ' times in this cycle without a usable checkpoint; not clearing')
    return false
  }
  // State first, with no await before it: a parallel caller sees the checkpoint phase at once.
  totalAsks += 1
  asks += 1
  phase = 'checkpoint'
  lastAskTokens = tokens
  askedAt = await $.clock.now()
  await ensureToken($)
  $.ui.toast('self-clear: context ' + Math.round(tokens / 1000) + 'K, asking for a checkpoint')
  return true
}

// The note folder must resolve inside the project before Claude is told to write there. If it does
// not (a link or alias a cloned repo ships), the mod stays off for this session and says so once.
async function folderOk($, cfg) {
  if (blocked) return false
  const place = await folderPlace($, cfg.dir)
  if (place === 'inside') return true
  if (place === 'unknown') {
    $.ui.log('self-clear: could not check where ' + cfg.dir + ' leads; skipping this ask', { to: 'debug' })
    return false
  }
  blocked = true
  gateOn = false
  $.ui.toast('self-clear: the note folder ' + cfg.dir + ' leads outside this project (a link?), so self-clear stays off in this session. Fix checkpointDir in .claude/self-clear.json and restart')
  return false
}

async function askForCheckpoint($, cfg, tokens) {
  if (!(await folderOk($, cfg))) { reset(); return }
  const first = totalAsks === 0
  if (!(await beginAsk($, tokens))) return
  if (first) await snapshotOld($, cfg, askedAt)
  // Not awaited: it resolves only when the new turn starts. A refusal ends the cycle.
  $.prompt.submit({ text: requestText(cfg, tokens, token) })
    .catch((err) => { drop(true); $.ui.log('self-clear: checkpoint request not sent: ' + err) })
}

// Spawn gate. The cycle acts only at a turn end, and a main loop that chains subagents in one turn
// (foreground fires, one after another) never reaches one. So once a clear is due, the main loop may
// not start a new subagent: the refusal reaches the model at once, mid-turn, and carries the checkpoint
// request with this cycle's token. Subagents already running finish; with nothing new started the work
// drains, the model ends its turn, and the turn end clears as before.
const GATE_HEAD = 'self-clear: no new subagent starts until this session is cleared. Subagents already running keep running. '
const GATE_CLEARING = 'self-clear: this session is being cleared now; start no subagent and end your turn.'
const GATE_AGAIN = 'self-clear: refused again. Start no subagent. Write the checkpoint with this line exactly, then end your turn:\n{tokenLine}'

// The refusal: the full request the first time in a cycle, then a short one that still names the token.
async function refuse($, cfg, tokens) {
  const tokenLine = await ensureToken($)
  gateRefusals += 1
  if (gateRefusals > 1) {
    $.ui.log('self-clear: spawn refused again (' + gateRefusals + ' in this cycle)', { to: 'debug' })
    return { deny: fill(GATE_AGAIN, { tokenLine }) }
  }
  return { deny: GATE_HEAD + requestText(cfg, tokens, tokenLine) }
}

async function clearThenResume($, cfg, checkpoint, attempt, gen, want) {
  // Input arrived between the checkpoint and now: the checkpoint no longer covers the session.
  if (userSpoke || lateInput || gen !== inputGen || token !== want) {
    const why = userSpoke ? 'you sent a message' : 'new input arrived (a job or a subagent finished)'
    drop()
    $.ui.toast('self-clear: ' + why + ', so this clear was cancelled; it will ask again later')
    return
  }
  try {
    // A refused run rejects (CommandRunResult has no deny field); the catch below retries.
    // A /clear that never settles must not leave the session stuck in 'clearing'.
    if (attempt === 1) {
      $.clock.after(CLEAR_WATCHDOG_MS, () => {
        if (phase === 'clearing' && token === want) {
          abandoned = want
          $.ui.log('self-clear: /clear did not finish; dropping this cycle')
          drop()
        }
      })
    }
    await $.command.run({ command: 'clear' })
    if (abandoned === want) {
      // Finished after the watchdog gave up. The session was cleared, so resume, unless a newer cycle runs.
      if (phase === 'idle' && cfg.autoResume) {
        $.prompt.submit({ text: fill(cfg.resumePrompt, { checkpoint }) })
          .catch((err) => $.ui.log('self-clear: resume prompt not sent: ' + err))
      }
      return
    }
    reset()
    dropStreak = 0
    pausedBelow = 0
    $.ui.toast('self-clear: cleared after checkpoint ' + checkpoint + (cfg.autoResume ? ', resuming' : ''))
    if (cfg.autoResume) {
      $.prompt.submit({ text: fill(cfg.resumePrompt, { checkpoint }) })
        .catch((err) => $.ui.log('self-clear: resume prompt not sent: ' + err))
    }
  } catch (err) {
    if (attempt < RETRIES) {
      $.clock.after(RETRY_MS, () => clearThenResume($, cfg, checkpoint, attempt + 1, gen, want))
      return
    }
    drop()
    $.ui.log('self-clear: /clear did not run: ' + err)
  }
}

export function register(on, options) {
  on('session.start', async ($, e, next) => {
    if (!tokenTag) tokenTag = (await $.session.id()).slice(0, 8) + '-' + (await $.clock.now()).toString(36)
    await $.command.register({ name: 'self-clear', description: 'Show self-clear status; "/self-clear now" starts the checkpoint-and-clear cycle', argumentHint: '[now]' })
    // Read the project file once at the start, so a project that turns the mod on says so right away.
    try { await loadConfig($, options) } catch (err) { $.ui.log('self-clear: ' + err, { to: 'debug' }) }
    return next(e)
  })

  // Stop lists the session's in-flight background work; remember how much is still running.
  on('classic.Stop', async ($, e, next) => {
    if (!e.agent_id) {
      backgroundTasks = Array.isArray(e.background_tasks)
        ? e.background_tasks.filter((t) => !(t && typeof t.command === 'string' && TIMER.test(t.command))).length
        : 0
    }
    return next(e)
  })

  // Spawn gate: see GATE_HEAD. Main loop only; a subagent's own subagents are part of its running work.
  // A failing guard is skipped by the engine and the subagent starts: the gate fails open, never shut.
  on('agent.spawn', async ($, e, next) => {
    // Not gated: a subagent's own subagents, and a workflow's agents (a running job; its text goes to the script).
    if (e.parentAgentId || e.workflow) return next(e)
    // The person spoke during the cycle: their work comes first, and this cycle could not clear anyway.
    if (userSpoke && phase === 'checkpoint' && gateOn) {
      drop()
      gateSuspended -= 1   // this spawn is the first of the ones let through
      $.ui.toast('self-clear: you sent a message during the checkpoint, so this cycle stopped and your work goes first; it will ask again later')
      return next(e)
    }
    if (phase === 'idle') {
      if (gateSuspended > 0) {
        gateSuspended -= 1
        return next(e)
      }
      const tokens = await contextTokens($)
      if (tokens < MIN_THRESHOLD) return next(e)            // no config read on the common path
      const cfg = await loadConfig($, options)
      if (!cfg.enabled || !cfg.gateSpawns || tokens < cfg.threshold || paused(tokens)) return next(e)
      if (phase !== 'idle') return refuse($, cfg, tokens)   // a parallel spawn started the cycle meanwhile
      if (!(await folderOk($, cfg))) return next(e)
      if (phase !== 'idle') return refuse($, cfg, tokens)
      if (!(await beginAsk($, tokens))) return next(e)       // unreachable while idle (totalAsks is 0); fail open
      await snapshotOld($, cfg, askedAt)
      return refuse($, cfg, tokens)
    }
    if (readyBusy) return next(e)
    const cfg = await loadConfig($, options)
    if (!cfg.enabled || !cfg.gateSpawns) return next(e)
    if (phase === 'clearing') return { deny: GATE_CLEARING }
    return refuse($, cfg, await contextTokens($))
  })

  // Prompts run in order. A prompt from this mod (the checkpoint request) starts a turn whose
  // checkpoint covers everything before it; any other prompt after it makes that checkpoint stale.
  on('prompt.submit', async ($, e, next) => {
    if (phase !== 'idle') {
      inputGen += 1   // first, with no await before it: a turn end already in flight must see it
      const kind = e.origin && e.origin.kind
      // Only this mod's own ask counts as its own; another plugin's prompt is machinery, or a person
      // when it is sent as the person's words (asUser).
      const own = kind === 'plugin' && e.origin.name === $.plugin.name && !e.origin.asUser
      if (own) {
        userSpoke = false   // this mod's own ask: its checkpoint covers what came before
      } else if (MACHINE_ORIGINS.includes(kind) && !(e.origin && e.origin.asUser)) {
        // New input that is not a person (a job finished, a subagent handed back): do not cancel,
        // but a checkpoint written before it no longer covers the session. Only a newer one, with a
        // new token, counts, and the cycle keeps one more ask for it (at most MAX_MACHINE_REASKS).
        if (phase === 'checkpoint') {
          machineReasks += 1
          // With the gate on, no new subagent starts, so hand-backs during the drain are bounded by the subagents
          // already running: they still make the checkpoint stale, but the cycle is dropped only when the gate is off.
          if (machineReasks > MAX_MACHINE_REASKS && !gateOn) {
            drop()
            $.ui.toast('self-clear: input keeps arriving during the checkpoint, so this cycle was dropped; it will ask again later')
          } else {
            // A new token at once, with no await before it: only a checkpoint written after this
            // input, carrying this token, counts. askedAt follows; a file with the new token cannot
            // exist before the next ask, so its later update leaves no gap.
            token = nextToken()
            askedAt = await $.clock.now()
            if (asks >= ASKS) asks = ASKS - 1
          }
        } else if (phase === 'clearing') {
          lateInput = true   // too late for a new checkpoint: cancel
        }
      } else {
        userSpoke = true
      }
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    // Taken before anything is awaited: any input from here on makes this turn end's checks stale.
    const gen = inputGen
    const want = token
    const result = await next(e)
    // Main conversation only.
    if (e.agentId) return result
    if (phase === 'clearing') return result
    if (e.isAborted) {
      // The person stopped Claude: abandon any cycle in progress.
      if (phase !== 'idle') {
        $.ui.log('self-clear: stopped by the user; not clearing')
        drop()
      }
      return result
    }
    const tokens = await contextTokens($)
    if (phase === 'idle' && tokens < MIN_THRESHOLD) {
      pausedBelow = 0   // well below any threshold (after a clear or a compaction): the pause is over
      dropStreak = 0
      return result
    }
    const cfg = await loadConfig($, options)
    if (!cfg.enabled) {
      reset()
      return result
    }
    if (phase === 'checkpoint') {
      const checkpoint = await freshCheckpoint($, cfg, askedAt, token)
      if (checkpoint) {
        const busy = await runningWork($)
        if (busy > 0) {
          $.ui.status('self-clear: checkpoint ready; waiting for ' + busy + ' background job(s) before /clear (stop that work to let the clear run)')
          // Work that never ends (a dev server, a watcher) must not hold the spawn gate shut for good.
          if (++busyWaits >= MAX_WAIT_TURNS && !readyBusy) {
            readyBusy = true
            $.ui.log('self-clear: background work keeps running; new subagents may start again, the clear still waits for it')
          }
          return result
        }
        // An input arrived while this turn end was checking: the checkpoint it found may not cover it.
        // Do not clear now; the next turn end checks again against the token that input set.
        if (gen !== inputGen || token !== want) return result
        phase = 'clearing'
        $.clock.after(0, () => clearThenResume($, cfg, checkpoint, 1, gen, want))
      } else if (asks < ASKS) {
        await askForCheckpoint($, cfg, tokens)
      } else {
        const names = skippedNames.slice(0, 3).join(', ')
        const reused = reusedNames.slice(0, 3).join(', ')
        drop(true)
        $.ui.toast(names
          ? 'self-clear: found ' + names + ', but a note name may only use letters, digits, ".", "_" and "-"; not clearing. It asks again later'
          : reused ? 'self-clear: found ' + reused + ', but that note was already in the folder before this cycle; a new file is needed. Not clearing. It asks again later'
          : 'self-clear: no new checkpoint with this cycle\'s one-time code was written; not clearing. It asks again later')
      }
      return result
    }
    if (blocked) return result
    if (tokens < cfg.threshold) {
      pausedBelow = 0   // the context went back below the threshold (a clear or a compaction): the pause is over
      dropStreak = 0
      waitedTurns = 0
      return result
    }
    if (paused(tokens)) return result
    if ((await runningWork($)) === 0) {
      waitedTurns = 0
      await askForCheckpoint($, cfg, tokens)
    } else if (tokens >= cfg.threshold + WAIT_MARGIN && ++waitedTurns >= MAX_WAIT_TURNS) {
      // Background work never seems to end; ask now. The clear itself still waits for running work.
      waitedTurns = 0
      await askForCheckpoint($, cfg, tokens)
    }
    return result
  })

  on('command.run', { command: 'self-clear' }, async ($, e) => {
    const cfg = await loadConfig($, options)
    const tokens = await contextTokens($)
    if (String(e.args || '').trim() === 'now') {
      if (!cfg.enabled) return { text: 'self-clear is off here: add {"enabled": true} to ' + PROJECT_FILE + '.' }
      if (phase !== 'idle') return { text: 'A cycle is already running (' + phase + ').' }
      if (!(await folderOk($, cfg))) {
        return { text: blocked
          ? 'self-clear is off in this session: the note folder ' + cfg.dir + ' leads outside this project.'
          : 'self-clear could not check where the note folder ' + cfg.dir + ' leads; try again in a moment.' }
      }
      reset()
      pausedBelow = 0
      dropStreak = 0
      phase = 'checkpoint'   // first: a spawn in between is refused (and gets the same token), it does not start a second ask
      askedAt = await $.clock.now()
      await ensureToken($)
      // Sent after this command returns: a prompt cannot start from inside the command's own hook.
      $.clock.after(0, () => askForCheckpoint($, cfg, tokens))
      return { text: 'Asking for a checkpoint; /clear follows once it is written.' }
    }
    return {
      text:
        'context ' + Math.round(tokens / 1000) + 'K · threshold ' + Math.round(cfg.threshold / 1000) + 'K · ' +
        (blocked ? 'off in this session (the note folder leads outside the project)'
          : cfg.enabled ? 'on' : cfg.bad ? 'off (' + PROJECT_FILE + ' is ' + cfg.bad + ')'
          : cfg.hasFile ? 'off in this project' : 'off (no ' + PROJECT_FILE + ')') +
        (pausedBelow > tokens ? ' · paused until ' + Math.round(pausedBelow / 1000) + 'K' : '') +
        ' · auto-resume ' + (cfg.autoResume ? 'on' : 'off') +
        ' · spawn gate ' + (cfg.gateSpawns ? 'on' : 'off') +
        ' · checkpoint ' + cfg.dir + '/' + cfg.prefix + '* · phase ' + phase,
    }
  })
}
